// Staff Dashboard — manage exams and view results
import React, { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Layout from '../../components/common/Layout';
import { examAPI } from '../../services/api';
import toast from 'react-hot-toast';

export default function StaffDashboard() {
  const [exams, setExams] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    examAPI.getAll().then(data => setExams(data.exams || [])).finally(() => setLoading(false));
  }, []);

  const togglePublish = async (exam) => {
    try {
      await examAPI.update(exam.id, { ...exam, is_published: !exam.is_published });
      setExams(prev => prev.map(e => e.id === exam.id ? { ...e, is_published: !e.is_published } : e));
      toast.success(exam.is_published ? 'Exam unpublished' : 'Exam published!');
    } catch {}
  };

  const deleteExam = async (id) => {
    if (!window.confirm('Delete this exam?')) return;
    try {
      await examAPI.delete(id);
      setExams(prev => prev.filter(e => e.id !== id));
      toast.success('Exam deleted');
    } catch {}
  };

  if (loading) return <Layout title="Staff Dashboard"><div className="flex justify-center py-20"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600"/></div></Layout>;

  return (
    <Layout title="Staff Dashboard">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-lg font-semibold text-gray-700">Your Exams ({exams.length})</h2>
        <Link to="/staff/exams/create" className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition">
          + Create New Exam
        </Link>
      </div>

      {exams.length === 0 ? (
        <div className="bg-white rounded-xl shadow-sm p-12 text-center">
          <div className="text-5xl mb-4">📝</div>
          <p className="text-gray-500">No exams yet. Create your first exam!</p>
          <Link to="/staff/exams/create" className="mt-4 inline-block bg-green-600 text-white px-5 py-2 rounded-lg">Create Exam</Link>
        </div>
      ) : (
        <div className="grid gap-4">
          {exams.map(exam => (
            <div key={exam.id} className="bg-white rounded-xl shadow-sm p-5 flex flex-col md:flex-row md:items-center gap-4">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-1">
                  <h3 className="font-bold text-gray-800">{exam.title}</h3>
                  <span className={`px-2 py-0.5 text-xs rounded-full font-medium ${exam.is_published ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}`}>
                    {exam.is_published ? 'Published' : 'Draft'}
                  </span>
                </div>
                <p className="text-sm text-gray-500">{exam.subject} · {exam.duration_minutes} mins · {exam.total_marks} marks</p>
                <p className="text-xs text-gray-400 mt-1">
                  Start: {new Date(exam.start_time).toLocaleString()} | End: {new Date(exam.end_time).toLocaleString()}
                </p>
              </div>
              <div className="flex gap-2 flex-wrap">
                <button
                  onClick={() => navigate(`/admin/monitor/${exam.id}`)}
                  className="bg-blue-50 hover:bg-blue-100 text-blue-700 px-3 py-1.5 rounded-lg text-sm font-medium transition"
                >
                  Monitor
                </button>
                <button
                  onClick={() => togglePublish(exam)}
                  className={`${exam.is_published ? 'bg-yellow-50 text-yellow-700 hover:bg-yellow-100' : 'bg-green-50 text-green-700 hover:bg-green-100'} px-3 py-1.5 rounded-lg text-sm font-medium transition`}
                >
                  {exam.is_published ? 'Unpublish' : 'Publish'}
                </button>
                <button
                  onClick={() => deleteExam(exam.id)}
                  className="bg-red-50 hover:bg-red-100 text-red-600 px-3 py-1.5 rounded-lg text-sm font-medium transition"
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </Layout>
  );
}
